{"query":"
  query getTextSearchResults(
    $ui_blocks: [UIBlockType!]
    $ui_features: [UIFeatureType!]
    $ui_layouts: [UILayoutType!]
    $ui_targets: [UITargetType!]
    $ui_themes: [UIThemeType!]
    $location: LocationInput!
    $url: String
    $options: SearchOptionsInput
    $uuid: String!
  ) {
    results: text_search(
      location: $location
      url: $url
      options: $options
      capabilities: {
        ui_blocks: $ui_blocks
        ui_features: $ui_features
        ui_themes: $ui_themes
        ui_targets: $ui_targets
        ui_layouts: $ui_layouts
      }
      uuid: $uuid
    ) {
      layoutGroups: ui_layout_groups {
        data: ui_layouts {
          ...uiLayoutFields
        }
      }
      meta {
        options {
          query
          recent_searches {
            search_term
            date_time
            pill_id
          }
        }
        uuid
      }
    }
  }

  fragment uiBasicComponentFields on UIBasicRowComponent {
    typeName: __typename
    ... on UIBasicRowTextContent {
      key
      textContent: content {
        ...uiLineFields
      }
    }
    ... on UIBasicRowImageContent {
      key
      imageContent: content {
        ... on Icon {
          name
        }
      }
    }
  }


  fragment uiBlockFieldsSearch on UIBlock {
    ...uiBlockFields
    ... on UIBasicRow {
      key
      trackingId: tracking_id
      target {
        ...uiTargetFieldsSearch
      }
      contentMain: content_main {
        ...uiBasicComponentFields
      }
    }
  }



  fragment uiRooBlockFields on UIRooBlock {
    data
    rooTemplateId: roo_template_id
    key
    trackingId: tracking_id
    trackingProperties: tracking_properties
  }

  fragment uiBlockFields on UIBlock {
    typeName: __typename
    ... on UIBanner {
      adServeId: ad_serve_id
      key
      header
      caption
      backgroundColor: background_color {
        ...colorFields
      }
      buttonCaption: button_caption
      contentDescription: content_description
      target {
        ...uiTargetFields
      }
      images {
        icon {
          ...iconFields
        }
        image
      }
      theme: ui_theme
      trackingId: tracking_id
      trackingProperties: tracking_properties
    }
    ... on UIButton {
      ...uiButton
    }
    ... on UIShortcut {
      key
      images {
        default
      }
      name
      contentDescription: content_description
      nameColor: name_color {
        ...colorFields
      }
      backgroundColor: background_color {
        ...colorFields
      }
      target {
        ...uiTargetFields
      }
      theme: ui_theme
      trackingId: tracking_id
    }
    ... on UICard {
      key
      trackingId: tracking_id
      trackingProperties: tracking_properties
      theme: ui_theme
      contentDescription: content_description
      border {
        ...uiCardBorderFields
      }
      target {
        ...uiTargetFields
      }
      uiContent: properties {
        default {
          ...uiHomeCardFields
        }
        expanded {
          ...uiHomeCardFields
        }
      }
    }
    ... on UIMerchandisingCard {
      key
      headerImageUrl: header_image_url
      backgroundImageUrl: background_image_url
      contentDescription: content_description
      uiLines: ui_lines {
        ...uiLines
      }
      buttons {
        key
        target {
          ...uiTargetFields
        }
        text
      }
      theme: ui_theme
      responsiveImage: image {
        ...uiResponsiveImage
      }
      cardBackgroundColor: background_color {
        ...colorFields
      }
      buttonCaption: button_caption
      target {
        ...uiTargetFields
      }
      trackingId: tracking_id
    }
    ... on UICategoryPill {
      ...uiCategoryPillFields
    }
    ... on UITallMenuItemCard {
      ...uiTallMenuItemCardFields
    }
    ... on UIStoryCard {
      ...uiStoryCardFields
    }
    ... on UIRooBlock {
      ...uiRooBlockFields
      entityDrnId: entity_drn_id
    }
  }


  fragment colorFields on Color {
    hex
    red
    green
    blue
    alpha
    token
  }


  fragment colorGradientFields on ColorGradient {
    from {
      ...colorFields
    }
    to {
      ...colorFields
    }
  }


  fragment currencyFields on Currency {
    code
    formatted
    fractional
    presentational
  }


  fragment iconFields on DeliverooIcon {
    name
    image
  }


  fragment illustrationBadgeFields on DeliverooIllustrationBadge {
    name
    image
  }


  fragment uiTargetFields on UITarget {
    typeName: __typename
    ... on UITargetRestaurant {
      ...uiTargetRestaurant
    }
    ... on UITargetParams {
      ...uiTargetParamsFields
    }
    ... on UITargetAction {
      action
      layoutId: layout_id
      params {
        id
        value
      }
    }
    ... on UITargetMenuItem {
      ...uiTargetMenuItem
    }
    ... on UITargetDeepLink {
      webTarget: fallback_target {
        uri: url
      }
    }
    ... on UITargetMenuItemModifier {
      ...uiTargetMenuItemModifier
    }
    ... on UITargetWebPage {
      url
      newWindow: new_window
    }
    ... on UITargetEditorialContent {
      id
    }
  }


  fragment uiTargetFieldsSearch on UITarget {
    ...uiTargetFields
    ... on UITargetAutocompleteSuggestion {
      suggestion
      params {
        id
        value
      }
      uiTargetType: ui_target_type
    }
  }


  fragment uiTargetMenuItem on UITargetMenuItem {
    menuItem: menu_item {
      id
    }
    links {
      href
    }
    typeName: __typename
  }


  fragment uiTargetMenuItemModifier on UITargetMenuItemModifier {
    restaurantId: restaurant_id
    menuItemId: menu_item_id
    uiTargetType: ui_target_type
  }


  fragment uiTargetParamsFields on UITargetParams {
    params {
      id
      value
    }
    queryParams: query_params
    title
    typeName: __typename
  }


  fragment uiTargetRestaurant on UITargetRestaurant {
    restaurant {
      id
      name
      links {
        self {
          href
        }
      }
    }
    typeName: __typename
  }


  fragment uiLayoutFields on UILayout {
    typeName: __typename
    ... on UILayoutList {
      header
      key
      blocks: ui_blocks {
        ...uiBlockFieldsSearch
      }
      trackingId: tracking_id
    }
    ... on UILayoutCarousel {
      key
      target {
        ...uiTargetFields
      }
      uiLines: ui_lines {
        ...uiLines
      }
      targetPresentational: target_presentational
      trackingId: tracking_id
      blocks: ui_blocks {
        ...uiBlockFieldsSearch
      }
    }
  }


  fragment uiButton on UIButton {
    key
    text
    contentDescription: content_description
    target {
      ...uiTargetFields
    }
    theme: ui_theme
    trackingId: tracking_id
    trackingProperties: tracking_properties
    line: ui_line {
      ...uiLines
    }
    type
  }


  fragment uiCardBorderFields on UICardBorderType {
    topColor: top_color {
      ...colorFields
    }
    bottomColor: bottom_color {
      ...colorFields
    }
    leftColor: left_color {
      ...colorFields
    }
    rightColor: right_color {
      ...colorFields
    }
    borderWidth: border_width
  }


  fragment uiHomeCardFields on UICardFields {
    bubble {
      uiLines: ui_lines {
        ...uiLines
      }
    }
    overlay {
      badges {
        key
        backgroundColor: background_color {
          ...colorFields
          ...colorGradientFields
        }
        spacing
        position
        text {
          ...uiLines
        }
      }
      background: background {
        typeName: __typename
        ...colorFields
        ...colorGradientFields
      }
      text {
        position
        color {
          ...colorFields
        }
        value
      }
      promotionTag: promotion_tag {
        primaryTagLine: primary_tag_line {
          backgroundColor: background_color {
            ...colorFields
            ...colorGradientFields
          }
          text {
            ...uiLines
          }
        }
        secondaryTagLine: secondary_tag_line {
          backgroundColor: background_color {
            ...colorFields
            ...colorGradientFields
          }
          text {
            ...uiLines
          }
        }
      }
    }
    favouritesOverlay: favourites_overlay {
      id
      entity
      isSelected: is_selected
      backgroundColor: background_color {
        ...colorFields
        ...colorGradientFields
      }
      selectedColor: selected_color {
        ...colorFields
      }
      unselectedColor: unselected_color {
        ...colorFields
      }
      target {
        ...uiTargetFields
      }
      countData: count_data {
        count
        isMaxCount: is_max_count
      }
    }
    countdownBadgeOverlay: countdown_badge_overlay {
      backgroundColor: background_color {
        ...colorFields
      }
      uiLine: ui_line {
        ...uiLines
      }
    }
    image
    uiLines: ui_lines {
      ...uiLines
    }
    illustrationBadge: illustration_badge {
      ...illustrationBadgeFields
    }
  }


  fragment uiCategoryPillFields on UICategoryPill {
    typeName: __typename
    blocks: content {
      ...uiLines
    }
    backgroundColor: background_color {
      typeName: __typename
      ...colorFields
    }
    target {
      ...uiTargetFields
    }
    trackingId: tracking_id
    contentDescription: content_description
  }


  fragment uiLineFields on UILine {
    typeName: __typename
    ... on UITextLine {
      key
      align
      spans: ui_spans {
        ...uiSpanFields
      }
      maxLines: max_lines
    }
    ... on UITitleLine {
      key
      text
      color {
        ...colorFields
      }
      size
    }
  }


  fragment uiLines on UILine {
    typeName: __typename
    ... on UITextLine {
      ...uiTextLine
    }
    ... on UITitleLine {
      key
      text
      color {
        ...colorFields
      }
      size
    }
    ... on UIBulletLine {
      key
      iconSpan: icon_span {
        typeName: __typename
        icon: span_icon {
          name
          size
          color {
            ...colorFields
          }
        }
      }
      bulletSpacerSpan: bullet_spacer_span {
        typeName: __typename
        width
      }
      spans: ui_spans {
        ...uiSpansPrimitive
      }
    }
  }


  fragment uiResponsiveImage on UIResponsiveImage {
    mobile
    desktop
  }



  fragment baseUiSpanFields on UISpan {
    typeName: __typename
    ... on UISpanText {
      key
      text
      size
      trackingId: tracking_id
      target {
        ...uiTargetFields
      }
      color {
        ...colorFields
      }
      isBold: is_bold
    }
    ... on UISpanSpacer {
      key
      width
    }
    ... on UISpanIcon {
      key
      icon: span_icon {
        name
        size
        color {
          ...colorFields
        }
      }
    }
    ... on UISpanPlusLogo {
      key
      plusLogoSize: size
      plusLogoColor: color {
        ...colorFields
      }
    }
    ... on UISpanCountdown {
      key
      endsAt: ends_at
      size
      color {
        ...colorFields
      }
      isBold: is_bold
    }
  }

  fragment uiSpanFields on UISpan {
    ...baseUiSpanFields
  }


  fragment uiSpansPrimitive on UISpan {
    typeName: __typename
    ... on UISpanIcon {
      key
      target {
        ...uiTargetFields
      }
      trackingId: tracking_id
      icon: span_icon {
        name
        size
        color {
          ...colorFields
        }
      }
    }
    ... on UISpanSpacer {
      key
      width
    }
    ... on UISpanText {
      key
      color {
        ...colorFields
      }
      text
      isBold: is_bold
      size
    }
    ... on UISpanRewardProgressBar {
      key
      steps
      completed
      rewardsType: rewards_type
    }
  }


  fragment uiStoryCardFields on UIStoryCard {
    preview {
      profile {
        imageUrl: image_url
        headingLines: heading_lines {
          ...uiLines
        }
      }
      video {
        ...videoContentFields
      }
      overlay {
        typeName: __typename
        ... on UIStoryTextOverlay {
          background {
            typeName: __typename
            ...colorFields
            ...colorGradientFields
          }
          uiLines: ui_lines {
            ...uiLines
          }
        }
      }
      target {
        ...uiTargetFields
      }
    }
    main {
      profile {
        imageUrl: image_url
        headingLines: heading_lines {
          ...uiLines
        }
      }
      video {
        sources {
          url
          type
        }
        placeholderImage: placeholder_url
        autoplay
        trackingId: tracking_id
      }
      overlay {
        typeName: __typename
        ... on UIStoryButtonOverlay {
          background {
            typeName: __typename
            ...colorFields
            ...colorGradientFields
          }
          contentLines: content {
            ...uiLines
          }
          button {
            key
            text
            contentDescription: content_description
            target {
              ...uiTargetFields
            }
            type
            trackingId: tracking_id
            trackingProperties: tracking_properties
          }
        }
      }
    }
    trackingId: tracking_id
    trackingProperties: tracking_properties
    key
  }


  fragment uiTallMenuItemCardFields on UITallMenuItemCard {
    id: menu_item_id
    title
    key
    image
    imageContent: image_content {
      url
      altText: alt_text
      type
    }
    target {
      ...uiTargetFields
    }
    price {
      ...currencyFields
    }
    discountedPrice: discounted_price {
      ...currencyFields
    }
    trackingId: tracking_id
    trackingProperties: tracking_properties
    isSponsored: is_sponsored
    priceInformationShort: price_information_short {
      ...uiLines
    }
    offerText: offer_text
  }


  fragment uiTextLine on UITextLine {
    typeName: __typename
    key
    align
    maxLines: max_lines
    spans: ui_spans {
      ...uiSpansPrimitive
      ... on UISpanCountdown {
        endsAt: ends_at
        isBold: is_bold
        size
        key
        color {
          ...colorFields
        }
      }
      ... on UISpanTag {
        target {
          typeName: __typename
          ... on UITargetAction {
            action
            layoutId: layout_id
            params {
              id
              value
            }
          }
        }
        key
        spans: ui_spans {
          ...uiSpansPrimitive
        }
        backgroundColor: background_color {
          ...colorFields
        }
      }
      ... on UISpanText {
        isStrikethrough: is_strikethrough
      }
    }
  }


  fragment videoContentFields on VideoContent {
    sources {
      url
      type
    }
    placeholderImage: placeholder_url
    autoplay
    trackingId: tracking_id
  }

","variables":{"ui_blocks":["BANNER"],"ui_layouts":["LIST"],"ui_targets":["PARAMS","RESTAURANT","MENU_ITEM"],"ui_themes":["BANNER_CARD","BANNER_EMPTY","BANNER_MARKETING_A","BANNER_MARKETING_B","BANNER_MARKETING_C","BANNER_PICKUP_SHOWCASE","BANNER_SERVICE_ADVISORY"],"location":{"geohash":"gcpvjdxczbu7","city_uname":"london","neighborhood_uname":"farringdon","postcode":""},"options":{"query":"","recent_searches":[]},"url":"https://deliveroo.co.uk/restaurants/london/farringdon?query=&linked-request-uuid=185963fc-6d7b-4536-baff-acb78c727562&geohash=gcpvjdxczbu7","uuid":"6def4f1e-a7d9-4cca-aa0b-4109007ecb8b","ui_features":["UNAVAILABLE_RESTAURANTS","LIMIT_QUERY_RESULTS","UI_CARD_BORDER","UI_CAROUSEL_COLOR","UI_PROMOTION_TAG","UI_BACKGROUND","ILLUSTRATION_BADGES","SCHEDULED_RANGES","UI_SPAN_TAGS","UI_SPAN_COUNTDOWN","UI_CARD_BADGES","TEXT_SEARCH_COMBINED_VIEW","UI_CAROUSEL_BACKGROUND_IMAGE","CARD_ILLUSTRATION_BADGE","HOME_MAP_VIEW"]}}

{"query":"
  query getHomeFeed(
    $ui_actions: [UIActionType!]
    $ui_blocks: [UIBlockType!]
    $ui_controls: [UIControlType!]
    $ui_features: [UIFeatureType!]
    $ui_layouts: [UILayoutType!]
    $ui_layout_carousel_styles: [UILayoutCarouselStyle!]
    $ui_lines: [UILineType!]
    $ui_targets: [UITargetType!]
    $ui_themes: [UIThemeType!]
    $fulfillment_methods: [FulfillmentMethod!]
    $location: LocationInput!
    $url: String
    $options: SearchOptionsInput
    $uuid: String!
  ) {
    results: search(
      location: $location
      options: $options
      url: $url
      capabilities: {
        ui_actions: $ui_actions
        ui_blocks: $ui_blocks
        ui_controls: $ui_controls
        ui_features: $ui_features
        ui_layouts: $ui_layouts
        ui_layout_carousel_styles: $ui_layout_carousel_styles
        ui_lines: $ui_lines
        ui_targets: $ui_targets
        ui_themes: $ui_themes
        fulfillment_methods: $fulfillment_methods
      }
      uuid: $uuid
    ) {
      layoutGroups: ui_layout_groups {
        id
        subheader
        data: ui_layouts {
          ...uiHomeLayoutFields
        }
      }

      controlGroups: ui_control_groups {
        appliedFilters: applied_filters {
          ...uiControlAppliedFilterFields
        }
        filters {
          ...uiControlFilterFields
        }
        sort {
          ...uiControlFilterFields
        }
        queryResults: query_results {
          ...uiControlQueryResultFields
        }
        fulfillmentMethods: fulfillment_methods {
          ...uiControlFulfillmentMethodFields
        }
      }

      modals: ui_modals {
        ...uiModalFields
        ...uiChallengesModalFields
        ...uiPlusFullScreenModalFields
        ...uiMerchandisingModalFields
        ...uiPromotionalModalFields
        ...uiPlusInviteModal
        ...uiPlusShortSignupModalFields
      }

      uiTargetModals: ui_target_modals {
        ...uiTargetModalFields
      }

      overlays: ui_feed_overlays {
        ...uiFeedOverlayFields
      }

      meta {
        ...searchResultMetaFields
      }
      capabilities
      rooBlockTemplates: roo_block_templates {
        ...uiRooBlockTemplateFields
      }
    }

    fulfillmentTimes: fulfillment_times(
      capabilities: {
        ui_actions: $ui_actions
        ui_blocks: $ui_blocks
        ui_controls: $ui_controls
        ui_features: $ui_features
        ui_layouts: $ui_layouts
        ui_layout_carousel_styles: $ui_layout_carousel_styles
        ui_lines: $ui_lines
        ui_targets: $ui_targets
        ui_themes: $ui_themes
        fulfillment_methods: $fulfillment_methods
      }
      fulfillment_methods: $fulfillment_methods
      location: $location
      uuid: $uuid
    ) {
      fulfillmentTimeMethods: fulfillment_time_methods {
        fulfillmentMethodLabel: fulfillment_method_label
        fulfillmentMethod: fulfillment_method
        asap {
          ...fulfillmentTimeOptionFields
        }
        days {
          day
          dayLabel: day_label
          times {
            ...fulfillmentTimeOptionFields
          }
        }
      }
    }
  }

  fragment uiControlAppliedFilterFields on UIControlAppliedFilter {
    label
    target_params {
      ...uiTargetParamsFields
    }
  }



  fragment uiRooBlockFields on UIRooBlock {
    data
    rooTemplateId: roo_template_id
    key
    trackingId: tracking_id
    trackingProperties: tracking_properties
  }

  fragment uiBlockFields on UIBlock {
    typeName: __typename
    ... on UIBanner {
      adServeId: ad_serve_id
      key
      header
      caption
      backgroundColor: background_color {
        ...colorFields
      }
      buttonCaption: button_caption
      contentDescription: content_description
      target {
        ...uiTargetFields
      }
      images {
        icon {
          ...iconFields
        }
        image
      }
      theme: ui_theme
      trackingId: tracking_id
      trackingProperties: tracking_properties
    }
    ... on UIButton {
      ...uiButton
    }
    ... on UIShortcut {
      key
      images {
        default
      }
      name
      contentDescription: content_description
      nameColor: name_color {
        ...colorFields
      }
      backgroundColor: background_color {
        ...colorFields
      }
      target {
        ...uiTargetFields
      }
      theme: ui_theme
      trackingId: tracking_id
    }
    ... on UICard {
      key
      trackingId: tracking_id
      trackingProperties: tracking_properties
      theme: ui_theme
      contentDescription: content_description
      border {
        ...uiCardBorderFields
      }
      target {
        ...uiTargetFields
      }
      uiContent: properties {
        default {
          ...uiHomeCardFields
        }
        expanded {
          ...uiHomeCardFields
        }
      }
    }
    ... on UIMerchandisingCard {
      key
      headerImageUrl: header_image_url
      backgroundImageUrl: background_image_url
      contentDescription: content_description
      uiLines: ui_lines {
        ...uiLines
      }
      buttons {
        key
        target {
          ...uiTargetFields
        }
        text
      }
      theme: ui_theme
      responsiveImage: image {
        ...uiResponsiveImage
      }
      cardBackgroundColor: background_color {
        ...colorFields
      }
      buttonCaption: button_caption
      target {
        ...uiTargetFields
      }
      trackingId: tracking_id
    }
    ... on UICategoryPill {
      ...uiCategoryPillFields
    }
    ... on UITallMenuItemCard {
      ...uiTallMenuItemCardFields
    }
    ... on UIStoryCard {
      ...uiStoryCardFields
    }
    ... on UIRooBlock {
      ...uiRooBlockFields
      entityDrnId: entity_drn_id
    }
  }


  fragment colorFields on Color {
    hex
    red
    green
    blue
    alpha
    token
  }


  fragment colorGradientFields on ColorGradient {
    from {
      ...colorFields
    }
    to {
      ...colorFields
    }
  }


  fragment uiControlFilterFields on UIControlFilter {
    id
    header
    images {
      icon {
        name
        image
      }
    }
    optionsType: options_type
    options {
      count
      default
      name: header
      id
      selected
      target_params {
        ...uiTargetParamsFields
      }
    }
    styling {
      web {
        desktop {
          collapse
        }
        mobile {
          collapse
        }
      }
    }
  }


  fragment currencyFields on Currency {
    code
    formatted
    fractional
    presentational
  }


  fragment iconFields on DeliverooIcon {
    name
    image
  }


  fragment illustrationBadgeFields on DeliverooIllustrationBadge {
    name
    image
  }


  fragment uiControlFulfillmentMethodFields on UIControlFulfillmentMethod {
    label
    targetMethod: target_method
  }


  fragment fulfillmentTimeOptionFields on FulfillmentTimeOption {
    optionLabel: option_label
    selectedLabel: selected_label
    timestamp(format: UNIX)
    selectedTime: selected_time {
      day
      time
    }
  }



  fragment uiLayoutRooBlockFields on UILayoutRooBlock {
    data
    rooTemplateId: roo_template_id
    key
    trackingId: tracking_id
    trackingProperties: tracking_properties
  }

  fragment uiHomeLayoutFields on UILayout {
    typeName: __typename
    ... on UILayoutCarousel {
      style
      imageUrl: image_url
      backgroundImageUrl: background_image_url
      target {
        ...uiTargetFields
      }
      uiLines: ui_lines {
        ...uiLines
      }
      targetPresentational: target_presentational
      key
      blocks: ui_blocks {
        ...uiBlockFields
      }
      trackingId: tracking_id
      rows
      contentDescription: content_description
      customActions: custom_actions {
        ...uiCustomActionFields
      }
    }
    ... on UILayoutList {
      header
      key
      blocks: ui_blocks {
        ...uiBlockFields
      }
      direction
      trackingId: tracking_id
    }
    ... on UILayoutRooBlock {
      ...uiLayoutRooBlockFields
    }
  }


  fragment uiCustomActionFields on UICustomAction {
    key
    trackingId: tracking_id
    iconName: icon_name
    title
    target {
      ...uiTargetFields
    }
  }


  fragment uiControlQueryResultFields on UIControlQueryResult {
    header
    key
    resultTarget: result_target {
      ...uiTargetFields
    }
    targetPresentational: result_target_presentational
    trackingId: tracking_id
    options {
      key
