            name
          }
          trackingId: tracking_id
        }
        headerInfoRows: ui_header_info_rows {
          key
          image: ui_image {
            ...uiImageFields
          }
          lines: ui_lines {
            ...uiLineFields
          }
          target {
            ...uiTargetFields
          }
          badge {
            ...uiBadgeBlock
          }
          uiTooltip: ui_tooltip {
            key
            text
            defaultOpenThreshold: default_open_threshold
            trackingId: tracking_id
            sessionReset: session_reset
          }
