        }
        uiRows: ui_rows {
          ...uiHeaderRowFields
        }
        banners: ui_banners {
          typeName: __typename
          ... on UIPromoBanner {
            key
            backgroundColor: background_color {
              ...colorFields
            }
            lines: ui_lines {
              ...uiLineFields
            }
            image: ui_image {
              ...uiImageFields
            }
            badge {
              ...uiLineFields
            }
