    $capabilities: CapabilitiesInput
    $request_uuid: String
    $include_token: Boolean!
  ) {
    result: get_menu_meta(
      options: $options
      capabilities: $capabilities
      request_uuid: $request_uuid
    ) {
      categories {
        id
        name
      }

      items {
        ...itemFields
