          image: ui_image {
            ...uiImageFields
          }
          lines: ui_lines {
            ...uiLineFields
          }
          target {
            ...uiTargetFields
          }
          badge {
            ...uiBadgeBlock
          }
          uiTooltip: ui_tooltip {
            key
            text
            defaultOpenThreshold: default_open_threshold
            trackingId: tracking_id
            sessionReset: session_reset
          }
          trackingId: tracking_id
        }
        uiRows: ui_rows {
          ...uiHeaderRowFields
        }
        banners: ui_banners {
          typeName: __typename
          ... on UIPromoBanner {
            key
            backgroundColor: background_color {
              ...colorFields
            }
            lines: ui_lines {
              ...uiLineFields
            }
            image: ui_image {
              ...uiImageFields
            }
            badge {
              ...uiLineFields
            }
          }
          ... on UIPlusBanner {
            key
            lines: ui_lines {
              ...uiLineFields
            }
